const fixed = "pending";     // type: "pending"
let mutable = "pending";       // type: string (widened)

function setStatus(next: "pending" | "done") {
  fixed = next;   // Error: cannot assign to const
  mutable = next; // OK — mutable is string
}

const HTTP = {
  GET: "GET",
  POST: "POST",
} as const;

type Method = typeof HTTP[keyof typeof HTTP];
// "GET" | "POST" — not string

function route(method: Method) {
  console.log(method);
}

route(HTTP.GET); // OK

function parseInput(raw: string | number | null): number {
  if (raw === null) {
    return 0;
  }
  if (typeof raw === "string") {
    return Number.parseInt(raw, 10);
  }
  // raw narrowed to number
  return raw;
}

function unsafe(data: unknown): string {
  // Bad: bypasses checking
  // return data as string;

  if (typeof data !== "string") {
    throw new Error("Expected string");
  }
  return data; // narrowed to string
}
